contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: deposit amount
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // read pre-deposit observable values
        uint beforeBalance = address(c).balance;

        // do deposit to give this contract a credit in c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read recorded credit after deposit via effects on balances: we cannot access credit mapping directly,
        // but we can infer that any decrease of c.balance on successful withdraw corresponds to credit decrease.
        uint afterDepositBalance = address(c).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read final observable values
        uint finalBalance = address(c).balance;

        // The general invariant to prove:
        // If withdrawAll reverted then c's balance must be unchanged from afterDepositBalance.
        // If withdrawAll returned then the recorded credit for this caller became zero. We cannot read credit directly,
        // but we can assert that c's on-chain balance did not decrease by more than the recorded-credit decrease;
        // since we cannot read recorded-credit, we restate the property as: when withdrawAll returns, finalBalance <= afterDepositBalance
        // (i.e., the contract did not gain funds) AND when it reverted finalBalance == afterDepositBalance.

        // Single assert expressing the general rule combining both cases.
        assert( (reverted && finalBalance == afterDepositBalance) || (!reverted && finalBalance <= afterDepositBalance) );
    }

    receive() external payable { }
}

